      { q: "【健康保険法】任意適用事業所の認可に関する厚生労働大臣の権限は、全国健康保険協会管掌健康保険及び健康保険組合管掌健康保険のいずれについても、日本年金機構に委任されている。", a: "× 健保の私が整理するわね。任意適用の認可権限は[[協会けんぽも健保組合も一律に機構へ委任、ではない]]の。<br>[[協会けんぽの被保険者に係るものは機構へ／健康保険組合の被保険者に係るものは地方厚生局長等へ]]、と分かれているのよ。だから「いずれについても機構に委任」は×ね。", p: "任意適用の認可権限は協会けんぽ＝機構／健保組合＝地方厚生局長等。一律機構ではない。" }
