    note: 'DCは転職時に個人別管理資産を移換しやすい（ポータビリティ）。DBも一定要件で脱退一時金相当額を転職先の制度等へ移換できる。iDeCo（個人型DC）は、障害基礎年金で国民年金保険料の法定免除を受けている者でも加入できる。',
    cards: [
      { q: "【社会保険に関する一般常識】確定拠出年金は拠出する掛金の額が確定しているのに対し、確定給付企業年金は将来支給される給付の額があらかじめ定められている。", a: "○ 社一の市役あいよ。その通り。[[DCは「掛金」が確定（給付は運用次第）]]、[[DBは「給付額」が確定（運用リスクは事業主）]]。名前のとおりよ。だから○ね。", p: "DC＝掛金が確定（運用リスクは本人）。DB＝給付額が確定（運用リスクは事業主）。" },
      { q: "【社会保険に関する一般常識】確定給付企業年金の加入者の資格を喪失した者が転職先で他の確定給付企業年金の加入者となった場合、規約に定めがあるときは、脱退一時金相当額の移換を申し出ることができる。", a: "○ 社一の市役あいよ。その通り。DBも一定要件で[[脱退一時金相当額を転職先の制度へ移換]]できるの（ポータビリティ）。DCは資産そのものを移換しやすいわ。だから○ね。", p: "DBも規約の定め等により、転職先の制度へ脱退一時金相当額を移換できる。" },
      { q: "【社会保険に関する一般常識】障害基礎年金の受給権者であることにより国民年金保険料の法定免除を受けている者は、確定拠出年金の個人型年金（iDeCo）の加入者となることができる。", a: "○ 社一の市役あいよ。その通り。[[法定免除を受けている者でもiDeCoに加入できる]]の。保険料免除と私的年金への加入は別の話なのよ。だから○ね。", p: "法定免除を受けている者でもiDeCo（個人型DC）に加入できる。" },
    ],
