    note: '雇用・健保とも、事業主が「賃金を支払う都度」、被保険者手帳（日雇労働被保険者手帳／日雇特例被保険者手帳）に印紙（雇用保険印紙／健康保険印紙）を貼り消印して印紙保険料を納付する（徴収法23条／健保169条）。「使用する日ごと」ではなく「賃金を支払う都度」が正しい。給付要件「前2か月に通算26日分」は雇用（日雇労働求職者給付金）と健保（日雇特例の療養の給付）で共通の数字で、健保はこれに加え「前6か月に通算78日分」でもよい。日雇労働被保険者は「日々雇用」又は「30日以内の期間を定めて雇用」される者で適用区域居住等の要件もある。なお労基では、日々雇い入れられる者は解雇予告の適用除外（1か月超で適用）という別論点がある。',
