    note: '認定決定はいずれも「政府が額を決定→納期限を指定して納入告知（概算の認定決定は納付書）」という流れは同じ。差が出るのは追徴金で、概算保険料には追徴金がなく、確定保険料は不足額（納付すべき額）の10%、印紙保険料は25%。いずれも1,000円未満の端数は切り捨てて計算。天災その他やむを得ない理由があるときは追徴金は課されない。【納付期限】認定決定された保険料・追徴金の納付期限は、政府が指定する期限＝その通知（納入告知書）を発する日から起算して30日を経過した日。この期限までに納付しないと督促が行われ、督促状の指定期限は「督促状を発する日から起算して10日以上経過した日」、さらに延滞金（原則年14.6%・納期限の翌日から2か月までは年7.3%）が課される。',
