    note: '一般被保険者だけが基本手当（日額×所定給付日数を繰り返し認定）。他の3区分は一時金（高年齢求職者給付金・特例一時金・日雇労働求職者給付金）。短期雇用特例被保険者の特例一時金は基本手当日額の30日分（当分の間40日分）で、受給期限は離職日の翌日から6か月。短期雇用特例被保険者が同一の事業主に1年以上引き続き雇用されると、一般被保険者等に切り替わる。なお健保にも「日雇特例被保険者」があるが、雇用保険の対応区分は「日雇労働被保険者」である点に注意。',
