    note: 'DBは給付建てのため掛金は規約で定め、月額一律の上限はなく原則事業主拠出（規約で加入者も一部拠出できるが、その掛金は事業主掛金を超えない）。企業型DCは事業主拠出が原則で、マッチング拠出により加入者も拠出できるが加入者掛金は事業主掛金を超えられない。他制度がなければ月55,000円、DB等があれば「55,000円−DB等の掛金相当額」。iDeCo（個人型DC）は本人拠出で、第1号68,000円（国民年金基金・付加保険料と合算）、第2号は企業年金なし23,000円・企業型DCやDB等あり20,000円・第3号23,000円。令和6年12月改正で、DB等加入者・公務員のiDeCo上限が月12,000円→20,000円に引き上げられた（iDeCoと企業年金掛金の合計が月55,000円以内）。',
    cards: [
      { q: "【社会保険に関する一般常識】個人型確定拠出年金（iDeCo）の拠出限度額は、国民年金の第1号被保険者については、国民年金基金の掛金等と合わせて月額68,000円である。", a: "○ 社一の市役あいよ。その通り。iDeCoの第1号は[[国民年金基金等と合算で月6.8万円（68,000円）]]が上限なの。自営業者などが対象ね。だから○ね。", p: "iDeCo第1号の拠出限度額＝月68,000円（国民年金基金等と合算）。" },
      { q: "【社会保険に関する一般常識】令和6年12月の改正により、確定給付企業年金などの他制度に加入する者及び公務員のiDeCoの拠出限度額は、月額1万2千円から2万円に引き上げられた。", a: "○ 社一の市役あいよ。その通り。R6.12改正で[[DB等加入者・公務員のiDeCo上限が12,000円→20,000円]]に上がったの（iDeCoと企業年金掛金の合計は月55,000円以内）。だから○ね。", p: "R6.12改正：DB等加入者・公務員のiDeCo上限が月12,000円→20,000円。" },
      { q: "【社会保険に関する一般常識】企業型確定拠出年金においてマッチング拠出を行う場合、加入者が拠出する掛金の額は、事業主が拠出する掛金の額を超えてはならない。", a: "○ 社一の市役あいよ。その通り。マッチング拠出の[[加入者掛金は事業主掛金を超えられない]]の。あくまで事業主拠出に上乗せする形なのよ。だから○ね。", p: "企業型DCのマッチング拠出：加入者掛金は事業主掛金を超えられない。" },
    ],
