    note: '健保の被扶養者の収入認定は「年間収入130万円未満（認定対象者が60歳以上、又は障害厚生年金を受けられる程度の障害者は180万円未満）」が原則。さらに、同一世帯なら被保険者の年間収入の2分の1未満（2分の1以上でも被保険者が世帯の生計の中心で、その年収を上回らなければ認定されることがある）、別居なら認定対象者の収入が被保険者からの仕送り額より少ないこと。収入には給与・事業収入だけでなく、公的年金・雇用保険の基本手当・傷病手当金などの継続的収入も含み、過去ではなく将来（認定以降1年間）の見込みで判断する。【税法の扶養との違い】所得税の扶養控除や、令和7年改正の「特定親族特別控除」（19歳以上23歳未満で年収150万円まで等）は所得税法上の基準であり、健保の被扶養者認定（130万円・180万円）とは別物。年齢別の150万円等は健保の被扶養者には適用されない。',
