    note: '任意適用事業所＝強制適用事業所でない事業所（個人事業で非適用業種、又は常時5人未満の個人事業など）。加入は、使用される者（適用除外者を除く被用者）の2分の1以上の同意を得て事業主が申請し厚生労働大臣の認可で適用事業所となる（被保険者資格を取得）。取消は、被保険者の4分の3以上の同意を得て申請し認可を受けると適用事業所でなくなり、被保険者は全員資格を喪失する。「加入1/2・取消3/4」の同意割合の差が頻出。いずれも認可制で、同意が整っても申請するかは事業主の任意（健保では加入・取消とも申請義務は生じない）。なお「任意特定適用事業所」は別概念で、特定適用事業所（従業員51人超）でない事業所が労使の合意（厚年は被保険者の過半数の同意等）に基づき申出をして、短時間労働者を適用拡大の対象とするもの。',
