    note: '所在不明による支給停止は、いずれも「所在が1年以上明らかでない」ことが要件。受給権者本人ではなく、他の受給権者・同順位者・次順位者等の「申請」によって、所在が明らかでなくなった時にさかのぼって支給停止される（職権ではなく申請が必要）。所在不明だった者は、いつでも支給停止の解除を申請できる。遺族基礎年金は配偶者と子の間（又は子相互）で調整。遺族厚生年金は他の受給権者の申請。遺族補償年金（労災）は同順位者があれば同順位者、なければ次順位者の申請で停止し、転給と関係する。加給年金額・子の加算は、加算の対象者（配偶者・子）が1年以上所在不明のとき受給権者の申請で加算分が支給停止。',
