    note: '人身拘束・足止めを防ぐ規定群。賠償予定の禁止は、違約金や損害賠償「額」をあらかじめ定める契約を禁じるもので、現実に生じた損害について賠償を請求すること自体は禁止していない。前借金相殺の禁止は、前借金等労働を条件とする前貸債権と賃金との相殺の禁止（労働者が真に任意で相殺に同意した場合の議論はあるが原則禁止）。強制貯金の禁止は労働契約に付随する強制的な貯蓄を禁じるが、労働者の任意の社内預金は労使協定の締結・届出・利子付与等の要件のもとで認められる。関連して、中間搾取の排除（法律に基づく場合を除き他人の就業に介入して利益を得てはならない）、強制労働の禁止（暴行・脅迫・監禁等による意思に反する労働の強制の禁止＝労基法で最も重い罰則）もある。',
