    note: '介護（補償）給付は、障害（補償）年金又は傷病（補償）年金を受ける権利を有する者で、その障害が第1級（すべて）又は第2級のうち精神神経・胸腹部臓器の障害に該当し、現に常時又は随時介護を受けている場合に、月を単位として支給される。額は常時介護・随時介護の区分ごとに、実際に介護に要した費用（上限額あり）。親族等による介護で費用を支出していない場合等でも最低保障額が支給される。障害者支援施設・特別養護老人ホーム・病院等に入所・入院している間は、介護がそこで行われるため支給されない。傷病補償年金・障害補償年金とあわせて受けられる。',
    cards: [
      { q: "【労働者災害補償保険法】介護補償給付は、障害補償年金又は傷病補償年金を受ける権利を有し、一定の障害により常時又は随時介護を要する状態にある者に対し、月を単位として支給される。", a: "○ 労災の私よ。その通り。介護（補償）給付は[[障害・傷病補償年金の受給者で、一定の障害により常時・随時介護を要する者]]に[[月単位]]で支給するの。だから○。", p: "介護（補償）給付＝障害・傷病補償年金受給者で常時・随時介護を要する者に月単位で支給。" },
      { q: "【労働者災害補償保険法】介護補償給付は、介護に要する費用を実際に支出していない場合には、一切支給されない。", a: "× 労災の私よ。違うの。親族の介護などで費用を支出していなくても、[[最低保障額が支給される]]の。だから「一切支給されない」は×よ。", p: "介護（補償）給付は費用支出がなくても最低保障額が支給される。" },
      { q: "【労働者災害補償保険法】障害者支援施設や特別養護老人ホーム等に入所している間は、介護補償給付は支給されない。", a: "○ 労災の私よ。その通り。[[施設に入所している間は介護（補償）給付は支給されない]]の。施設で介護が行われるからね。だから○。", p: "障害者支援施設・特養等に入所中は介護（補償）給付は支給されない。" },
    ],
