    note: '老齢基礎年金は保険料納付済期間480月（40年）で満額。満たない場合は月数に応じて減額（満額×反映月数÷480）。免除期間は、基礎年金の国庫負担が2分の1になった平成21年4月以降、全額免除＝2分の1（8分の4）、4分の3免除＝8分の5、半額免除＝8分の6、4分の1免除＝8分の7が年金額に反映される（国庫負担分は反映されるため、全額免除でも満額の半分は受け取れる）。平成21年3月以前の免除期間は国庫負担3分の1のため反映割合が低い（全額免除3分の1等）。学生納付特例・納付猶予の期間は、受給資格期間（10年）には算入されるが年金額には反映されない（10年以内に追納すれば反映）。',
