    tagline: '会社分割で、分割される事業に「主として従事」する労働者は、分割契約等に承継の定めがあれば当然に承継（異議不可）。定めがなければ異議申出で承継できる。主として従事しない労働者は、承継の定めがあれば異議申出で除外できる。',
