    note: '高額介護合算療養費は、同一世帯における1年間（毎年8月1日から翌年7月31日まで）の医療保険の自己負担額（高額療養費が支給される場合はそれを控除した後の額）と、介護保険の自己負担額（高額介護サービス費等を控除した後の額）を合算し、所得区分ごとに定められた年額の限度額を超えた場合に、その超えた額を支給するもの。医療保険者と介護保険者が、それぞれの自己負担額の割合に応じて按分して支給する。月単位で軽減する高額療養費・高額介護サービス費を補完し、医療と介護の負担が重い世帯の年間負担を軽減する。',
