    note: '過労死等防止対策推進法は、過労死等の防止のための対策を推進し、健康で充実して働き続けられる社会の実現を目指す理念法。「過労死等」とは、①業務における過重な負荷による脳血管疾患・心臓疾患を原因とする死亡、②業務における強い心理的負荷による精神障害を原因とする自殺による死亡、③これらの脳・心臓疾患・精神障害をいう。国の責務、調査研究等、国民の理解を深める啓発、相談体制の整備、民間団体の活動支援を定め、毎年11月を「過労死等防止啓発月間」とする。政府は過労死等の防止のための対策に関する大綱を定めなければならない。直接の罰則規定はない。',
